export const LANG_LABELS = { om: 'Afaan Oromo', am: 'አማርኛ', en: 'English' }
export const lang = ref('en')

export function t(key, params = {}) {
  const raw = messages[lang.value]?.[key] ?? messages.en[key] ?? key
  return raw.replace(/\{(\w+)\}/g, (_, k) => params[k] ?? '')
}
